import { Component, inject } from '@angular/core';
import { AsyncPipe } from '@angular/common';
import { ActivatedRoute } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { catchError, distinctUntilChanged, map, of, startWith, switchMap } from 'rxjs';

type Transaction = { id: string; description: string };
type ViewState =
  | { kind: 'loading'; accountId: string }
  | { kind: 'ready'; accountId: string; rows: Transaction[] }
  | { kind: 'error'; accountId: string };

@Component({
  selector: 'app-transaction-history',
  standalone: true,
  imports: [AsyncPipe],
  template: `
    @if (state$ | async; as state) {
      @switch (state.kind) {
        @case ('loading') { <p>Loading {{ state.accountId }}...</p> }
        @case ('error') { <p role="alert">History temporarily unavailable.</p> }
        @case ('ready') {
          <h2>Transactions for {{ state.accountId }}</h2>
          @for (row of state.rows; track row.id) {
            <p>{{ row.description }}</p>
          } @empty { <p>No transactions.</p> }
        }
      }
    }
  `
})
export class TransactionHistoryComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly http = inject(HttpClient);

  readonly state$ = this.route.paramMap.pipe(
    map(params => params.get('accountId')),
    distinctUntilChanged(),
    switchMap(accountId => {
      if (!accountId) return of<ViewState>({ kind: 'error', accountId: '' });
      return this.http.get<Transaction[]>(
        `/api/accounts/${encodeURIComponent(accountId)}/transactions`
      ).pipe(
        map(rows => ({ kind: 'ready' as const, accountId, rows })),
        startWith({ kind: 'loading' as const, accountId }),
        catchError(() => of({ kind: 'error' as const, accountId }))
      );
    })
  );
}

// Example shared domain contract agreed across frontend and backend.
// Save in a versioned contract package or generate from an OpenAPI schema.
export type CurrencyCode = 'INR' | 'USD';

export interface AccountSummaryDto {
  accountId: string; // opaque account reference
  maskedAccount: string;
  currency: CurrencyCode;
  postedMinor: number;
  availableMinor: number;
  asOf: string; // ISO 8601 timestamp
}

export function validateAccountSummary(
  value: AccountSummaryDto
): string[] {
  const issues: string[] = [];
  if (!value.accountId.trim()) issues.push('Missing account reference');
  if (!/^\*+[0-9]{2,4}$/.test(value.maskedAccount)) {
    issues.push('Expected a masked account label');
  }
  if (!Number.isSafeInteger(value.postedMinor)) {
    issues.push('Invalid posted minor units');
  }
  if (!Number.isSafeInteger(value.availableMinor)) {
    issues.push('Invalid available minor units');
  }
  if (Number.isNaN(Date.parse(value.asOf))) issues.push('Invalid timestamp');
  return issues;
}

// Demonstration validator. For external network inputs use a runtime
// schema validator and contract tests; static types do not validate JSON.

// Presentation-only utility. Do not use for financial ledger arithmetic.
export function formatMinorAmount(
  minor: number,
  currency: string,
  locale = 'en-IN'
): string {
  if (!Number.isSafeInteger(minor)) throw new Error('Invalid minor units');
  const currencyFormatter = new Intl.NumberFormat(locale, {
    style: 'currency', currency
  });
  const digits = currencyFormatter.resolvedOptions().maximumFractionDigits;
  if (digits === undefined) throw new Error('Unknown currency digits');
  const formattedMajor = minor / 10 ** digits;
  return currencyFormatter.format(formattedMajor);
}

// Example for two-decimal and zero-decimal currencies:
console.log(formatMinorAmount(12345, 'INR'));
console.log(formatMinorAmount(12345, 'JPY', 'ja-JP'));

// In high-value systems, avoid converting unsafe-range integers to Number;
// format via BigInt/decimal methods under an approved monetary model.

export interface TransactionAmount {
  amountMinor: number;
  currency: 'INR' | 'USD' | 'JPY';
}

export function renderTransactionAmount(
  transaction: TransactionAmount,
  locale: string
): string {
  if (!Number.isSafeInteger(transaction.amountMinor)) {
    throw new Error('Invalid amount');
  }
  const formatter = new Intl.NumberFormat(locale, {
    style: 'currency', currency: transaction.currency
  });
  const digits = formatter.resolvedOptions().maximumFractionDigits;
  if (digits === undefined) throw new Error('Unknown currency digits');
  return formatter.format(transaction.amountMinor / 10 ** digits);
}

// Regression guards: locale must not override the transaction currency.
const usd = renderTransactionAmount({ amountMinor: 5000, currency: 'USD' }, 'en-IN');
const inr = renderTransactionAmount({ amountMinor: 5000, currency: 'INR' }, 'en-IN');
if (usd === inr || !usd.includes('USD') && !usd.includes('$')) {
  throw new Error('Currency regression');
}
