// Shared request shape. Types do not replace runtime validation.
export interface TransferRequest {
  sourceAccountId: string;
  destinationAccountId: string;
  amountMinor: number;
  currency: 'INR';
  requestId: string; // idempotency key assigned to one logical request
}

export function validateTransferForm(request: TransferRequest): string[] {
  const errors: string[] = [];
  if (!request.sourceAccountId.trim()) errors.push('Choose a source account');
  if (!request.destinationAccountId.trim()) errors.push('Choose a destination');
  if (request.sourceAccountId === request.destinationAccountId) {
    errors.push('Choose a different destination');
  }
  if (!Number.isSafeInteger(request.amountMinor) || request.amountMinor <= 0) {
    errors.push('Enter a positive amount in minor units');
  }
  if (!request.requestId.trim()) errors.push('Missing request reference');
  return errors;
}

